import pytest

from toposort import order


def test_order_respects_dependencies():
    assert order(["a", "b", "c"], [("a", "b"), ("b", "c")]) == ["a", "b", "c"]


def test_order_breaks_ties_alphabetically():
    assert order(["banana", "apple", "cherry"], []) == ["apple", "banana", "cherry"]


def test_order_sorts_a_diamond():
    deps = [("a", "b"), ("a", "c"), ("b", "d"), ("c", "d")]
    assert order(["a", "b", "c", "d"], deps) == ["a", "b", "c", "d"]


def test_order_is_empty_without_tasks():
    assert order([], []) == []


def test_order_rejects_cycles():
    with pytest.raises(ValueError):
        order(["a", "b"], [("a", "b"), ("b", "a")])
    with pytest.raises(ValueError):
        order(["a"], [("a", "a")])
